  </dialog>
  <script>
    const featureContent = {
      memberships: "'`<div class="detail-top"><h3>Your people, together.</h3><span class="sample-label">Sample members</span></div><p class="detail-sub">A familiar face behind every membership.</p><div class="member-row"><span class="avatar" style="background:#e5eada">ES</span><div class="member-info"><p class="member-name">Elliot Shaw</p><p class="member-meta">Monthly membership</p></div><span class="status">Active</span></div><div class="member-row"><span class="avatar" style="background:#f1e1d8">MR</span><div class="member-info"><p class="member-name">Maya Rivers</p><p class="member-meta">Annual membership</p></div><span class="status">Active</span></div><div class="member-row"><span class="avatar">AK</span><div class="member-info"><p class="member-name">Alex Kim</p><p class="member-meta">Monthly membership</p></div><span class="status">Active</span></div><div class="detail-bottom"><span>Every member. One place.</span><strong>Memberships, sorted. <span aria-hidden="true">↗</span></strong></div>`,
      classes: `<div class="detail-top"><h3>A place for every session.</h3><span class="sample-label">Sample class</span></div><p class="detail-sub">Your class bookings, at a glance.</p><div class="booking-line"><strong>Better bouldering</strong><span>18:00 – 19:00</span></div><div class="booking-line" style="font-size:11px;color:var(--muted);margin-bottom:8px"><span>4 climbers booked</span><span>2 spaces left</span></div><div class="capacity"><span></span></div><div class="member-row" style="margin-top:20px"><span class="avatar" style="background:#f1e1d8">MR</span><div class="member-info"><p class="member-name">Maya Rivers</p><p class="member-meta">Better bouldering</p></div><span class="status">Booked</span></div><div class="member-row"><span class="avatar">AK</span><div class="member-info"><p class="member-name">Alex Kim</p><p class="member-meta">Better bouldering</p></div><span class="status">Booked</span></div><div class="detail-bottom"><span>Know who'"'s on the wall.</span><strong>Bookings, together. <span aria-hidden=\"true\">↗</span></strong></div>"'`,
      passes: `<div class="detail-top"><h3>Climbing starts here.</h3><span class="sample-label">Sample pass</span></div><p class="detail-sub">Keep a handle on every day at the wall.</p><div class="pass-ticket"><div><h4>One good session.</h4><p>Day pass · General admission</p></div><span class="ticket-icon"><svg class="icon" aria-hidden="true"><use href="#ticket"/></svg></span></div><div class="member-row"><span class="avatar" style="background:#e5eada">ES</span><div class="member-info"><p class="member-name">Elliot Shaw</p><p class="member-meta">Day pass · Today</p></div><span class="status">Checked in</span></div><div class="detail-bottom"><span>From the desk to the wall.</span><strong>Day passes, in order. <span aria-hidden="true">↗</span></strong></div>`
    };
    const tabs = [...document.querySelectorAll('"'[data-feature]')];
    const panel = document.getElementById('feature-panel');
    function selectFeature(tab, focus = false) {
      tabs.forEach(item => { const selected = item === tab; item.setAttribute('aria-selected', selected); item.tabIndex = selected ? 0 : -1; });
      document.getElementById('feature-card').innerHTML = featureContent[tab.dataset.feature];
      panel.setAttribute('aria-labelledby', tab.id);
      if (focus) tab.focus();
    }
    tabs.forEach((tab, index) => {
      tab.addEventListener('click', () => selectFeature(tab));
      tab.addEventListener('keydown', event => {
        let next;
        if (event.key === 'ArrowDown' || event.key === 'ArrowRight') next = (index + 1) % tabs.length;
        if (event.key === 'ArrowUp' || event.key === 'ArrowLeft') next = (index - 1 + tabs.length) % tabs.length;
        if (event.key === 'Home') next = 0;
        if (event.key === 'End') next = tabs.length - 1;
        if (next "'!== undefined) { event.preventDefault(); selectFeature(tabs[next], true); }
      });
    });
    selectFeature(tabs[0]);
    const dialog = document.getElementById('"'demo-dialog');
    const form = document.getElementById('demo-form');
    const message = document.getElementById('form-message');
    let dialogTrigger;
    document.querySelectorAll('[data-open-demo]').forEach(button => button.addEventListener('click', () => {
      dialogTrigger = button;
      form.hidden = false;
      message.hidden = true;
      document.getElementById('form-error').hidden = true;
      dialog.showModal();
      document.getElementById('name').focus();
    }));
    document.querySelector('.close-dialog').addEventListener('click', () => dialog.close());
    dialog.addEventListener('click', event => {if (event.target === dialog) { const r = dialog.getBoundingClientRect(); if(event.clientX < r.left || event.clientX > r.right || event.clientY < r.top || event.clientY > r.bottom) dialog.close(); }});
    dialog.addEventListener('close', () => dialogTrigger?.focus());
    form.addEventListener('submit', event => {
      event.preventDefault();
      const request = Object.fromEntries(new FormData(form));
      for(const field of ['name','gym']) { if("'!request[field].trim()) { const input = document.getElementById(field); input.setCustomValidity('"'Please enter ' + (field === 'name' ? 'your name.' : 'your gym name.')); input.reportValidity(); return; } }
      try {
        localStorage.setItem('tidepool-demo-request', JSON.stringify({...request, savedAt: new Date().toISOString()}));
        form.hidden = true;
        message.replaceChildren();
        const title = document.createElement('strong'); title.textContent = 'Your request is saved on this device.';
        const note = document.createElement('p'); note.textContent = 'Thanks, ' + request.name.trim() + '. This is a preview, so no request has been sent. Your gym details are ready for when demo scheduling is connected.';
        const done = document.createElement('button'); done.type = 'button'; done.className = 'button button-dark form-submit'; done.textContent = 'Done'; done.addEventListener('click', () => dialog.close());
        message.append(title,note,done); message.hidden = false; done.focus();
      } catch {
        const error = document.getElementById('form-error'); error.textContent = 'This browser could not save your request. Allow local storage and try again.'; error.hidden = false;
      }
    });
    form.querySelectorAll('input').forEach(input => input.addEventListener('input', () => input.setCustomValidity('')));
    const menu = document.querySelector('.menu-toggle');
    const nav = document.getElementById('navigation');
    function closeMenu() { nav.classList.remove('mobile-open'); menu.setAttribute('aria-expanded','false'); menu.setAttribute('aria-label','Open navigation'); }
    menu.addEventListener('click', () => {const open = nav.classList.toggle('mobile-open'); menu.setAttribute('aria-expanded',String(open)); menu.setAttribute('aria-label',open ? 'Close navigation' : 'Open navigation');});
    nav.querySelectorAll('a').forEach(link => link.addEventListener('click', closeMenu));
    document.addEventListener('keydown', event => { if(event.key === 'Escape' && nav.classList.contains('mobile-open')) {closeMenu();menu.focus();} });
    document.getElementById('year').textContent = new Date().getFullYear();
  </script>
</body>
</html>
EOF"

